// Helper function to get a question by ID and language
export const getQuestionById = (questionId, language) => {
  // Search in multilingual questions
  for (const expertise in multilingualKnowledgeQuestions) {
    for (const difficulty in multilingualKnowledgeQuestions[expertise]) {
      const questions = multilingualKnowledgeQuestions[expertise][difficulty];
      const question = questions.find(q => q.id === questionId);

      if (question) {
        const translation = question.translations[language.toLowerCase()];

        if (!translation) {
          console.warn(`No translation found for language: ${language}, falling back to English`);
          const englishTranslation = question.translations.english;
          return {
            id: question.id,
            question: englishTranslation.question,
            correctAnswer: englishTranslation.correctAnswer,
            language: 'english',
            expertise,
            difficulty
          };
        }

        return {
          id: question.id,
          question: translation.question,
          correctAnswer: translation.correctAnswer,
          language: language.toLowerCase(),
          expertise,
          difficulty
        };
      }
    }
  }

  // Fallback to old questions if not found in multilingual
  const oldQuestion = oldQuestions.find(q => q.id === questionId);
  if (oldQuestion) {
    return oldQuestion;
  }

  return null;
};

// Helper function to get a random question by criteria
export const getRandomQuestionByCriteria = (expertise, difficulty, language) => {
  const questions = multilingualKnowledgeQuestions[expertise]?.[difficulty] || [];

  if (questions.length === 0) {
    console.warn(`No multilingual questions found for expertise: ${expertise}, difficulty: ${difficulty}. Using fallback from old questions.`);

    // Fallback to old questions format
    let filteredQuestions = oldQuestions;

    if (expertise) {
      filteredQuestions = filteredQuestions.filter(q => q.expertise === expertise);
    }

    if (difficulty) {
      filteredQuestions = filteredQuestions.filter(q => q.difficulty === difficulty);
    }

    if (language) {
      filteredQuestions = filteredQuestions.filter(q => q.language === language.toLowerCase());
    }

    if (filteredQuestions.length === 0) {
      // If no questions in requested language, try English
      filteredQuestions = oldQuestions.filter(q =>
        q.expertise === expertise &&
        q.difficulty === difficulty &&
        q.language === 'english'
      );
    }

    if (filteredQuestions.length === 0) {
      console.error(`No questions found at all for expertise: ${expertise}, difficulty: ${difficulty}`);
      return null;
    }

    const randomIndex = Math.floor(Math.random() * filteredQuestions.length);
    return filteredQuestions[randomIndex];
  }

  const randomQuestion = questions[Math.floor(Math.random() * questions.length)];
  const translation = randomQuestion.translations[language.toLowerCase()];

  if (!translation) {
    console.warn(`No translation found for language: ${language}`);
    // Fallback to English if requested language not available
    const englishTranslation = randomQuestion.translations.english;
    return {
      id: randomQuestion.id,
      question: englishTranslation.question,
      correctAnswer: englishTranslation.correctAnswer,
      language: 'english',
      expertise,
      difficulty
    };
  }

  return {
    id: randomQuestion.id,
    question: translation.question,
    correctAnswer: translation.correctAnswer,
    language: language.toLowerCase(),
    expertise,
    difficulty
  };
};

// Get all available languages
export const getAvailableLanguages = () => {
  return ['english', 'hindi', 'tamil', 'telugu', 'marathi'];
};

// Get all expertise types
export const getAvailableExpertise = () => {
  return Object.keys(multilingualKnowledgeQuestions);
};

// Get all difficulty levels
export const getAvailableDifficulties = () => {
  return ['beginner', 'intermediate', 'expert'];
};
